for each ch in "a1B?" {
    printf("%s %d %d %d %d\n", ch, isalnum(ord(ch)) != 0, isalpha(ord(ch)) != 0, isdigit(ord(ch)) != 0, ispunct(ord(ch)) != 0)
}

list cs = [32, 9, 10, 127, ord("x")]
for each c in cs {
    printf("%d %d %d\n", isblank(c) != 0, iscntrl(c) != 0, isspace(c) != 0)
}

